    sequence: (this.state.integrations?.length ?? 0) + 1,
    ...(candidate ? { candidate } : {}),
    ...(tests ? { tests } : {}),
  });
  if (integration.kind === "conflict") {
    const files = integration.files.length ? ` (${integration.files.join(", ")})` : "";
