  assert.equal(fs.readFileSync(path.join(p.integrationWorktree, "file.txt"), "utf8"), "from u1\n");
  assert.equal(git(p.integrationWorktree, ["status", "--porcelain"]), "", "the merge is aborted, leaving a clean worktree");
