1	/**
2	 * Versioning and structural validation for the durable operation document.
3	 *
4	 * The operation document is the single source of truth for a durable operation. It is embedded in the task store
5	 * envelope, whose schema version (`CURRENT_STATE_SCHEMA_VERSION`) governs the envelope only: the envelope gate cannot
6	 * tell an older operation shape from a newer one. This module owns that second gate.
7	 *
8	 * Rules, in the order they are applied on load:
9	 *
10	 *   1. A record this build understands (current version) is validated and used as-is.
11	 *   2. A v1, v2, or v3 record (or one that predates the field, which reads as v1) is upgraded in memory by changing
12	 *      only the schema version. v4 adds explicit execution reservations; older parallel records are clamped to serial.
13	 *   3. A record from a newer build is refused. It is not corrupt: a build that wrote it can still read it, and
14	 *      quarantining it would destroy evidence. It is also never interpreted as if it were current.
15	 *
16	 * Migration is deliberately additive and lossless: the store writes a byte-identical `.pre-migration-vN` copy of the
17	 * whole record before the first write at a newer schema version (see `OperationStore.save`).
18	 */
19	import { unresolvedAssumptionsProblem, type DurableOperationState, type OperationPolicy, type WorkUnit } from "./operation.js";
20	import { specialistInputsProblem } from "./specialist_profiles.js";
21	import { parseBoundaryRules } from "./boundary_rules.js";
22	
23	/** The operation document version this build writes. Independent of the task-store envelope version. */
24	export const CURRENT_OPERATION_SCHEMA_VERSION = 4;
25	
26	/** The operation document version every released 1.0.0 build wrote. */
27	export const LEGACY_OPERATION_SCHEMA_VERSION = 1;
28	
29	const OPERATION_STATUSES = new Set(["RUNNING", "WAITING", "BLOCKED", "PAUSED", "COMPLETE", "CANCELLED"]);
30	const WORK_UNIT_STATUSES = new Set(["RUNNABLE", "RUNNING", "PARKED", "WAITING_ON_DEPENDENCY", "COMPLETE", "BLOCKED"]);
31	const DECISION_ACTION_KINDS = new Set([
32	  "retry",
33	  "keep_waiting",
34	  "assign",
35	  "revise",
36	  "replace_task",
37	  "set_inputs",
38	  "lift_context_budget",
39	  "drop",
40	  "cancel_operation",
41	  "accept_no_change",
42	]);
43	
44	/** The largest concurrency an operation may request. A cost bound, not a capacity claim. */
45	export const MAX_CONCURRENT_UNITS = 64;
46	
47	/** A record written by a build newer than this one. Never quarantined; never interpreted. */
48	export class UnsupportedOperationSchemaError extends Error {
49	  constructor(readonly recordVersion: unknown, readonly supportedVersion = CURRENT_OPERATION_SCHEMA_VERSION) {
50	    super(
51	      `operation record schema ${String(recordVersion)} is newer than this build supports (${supportedVersion}); upgrade Nexus to open it`,
52	    );
53	    this.name = "UnsupportedOperationSchemaError";
54	  }
55	}
56	
57	/** A record whose shape violates an invariant. The field and unit are named so the operator can repair the file. */
58	export class InvalidOperationStateError extends Error {
59	  constructor(message: string) {
60	    super(message);
61	    this.name = "InvalidOperationStateError";
62	  }
63	}
64	
65	/**
66	 * Brings a persisted operation document to the current version.
67	 *
68	 * Pure: the input is not mutated and no I/O happens. Throws `UnsupportedOperationSchemaError` for a newer record and
69	 * `InvalidOperationStateError` for a non-integer version or a failed invariant. `schemaVersion: 1` records gain the
70	 * version field and nothing else.
71	 */
72	export function migrateOperationState(raw: unknown): DurableOperationState {
73	  if (!raw || typeof raw !== "object" || Array.isArray(raw)) {
74	    throw new InvalidOperationStateError("operation record is not an object");
75	  }
76	  const record = raw as Partial<DurableOperationState> & { schemaVersion?: unknown };
77	  const version = record.schemaVersion;
78	  if (version === undefined) {
79	    // A very old record predates the field; it has the v1 shape.
80	    const migrated = { ...(record as object), schemaVersion: LEGACY_OPERATION_SCHEMA_VERSION };
81	    return migrateOperationState(migrated);
82	  }
83	  if (typeof version !== "number" || !Number.isInteger(version) || version < 0) {
84	    throw new InvalidOperationStateError(`operation record has an invalid schemaVersion (${JSON.stringify(version)})`);
85	  }
86	  if (version > CURRENT_OPERATION_SCHEMA_VERSION) throw new UnsupportedOperationSchemaError(version);
87	  if (version < LEGACY_OPERATION_SCHEMA_VERSION) {
88	    throw new InvalidOperationStateError(`operation record schema ${version} is not a version this build ever wrote`);
89	  }
90	  const migrated = version === CURRENT_OPERATION_SCHEMA_VERSION ? (record as DurableOperationState) : ({ ...record, schemaVersion: CURRENT_OPERATION_SCHEMA_VERSION } as DurableOperationState);
91	  validateOperationState(migrated);
92	  return migrated;
93	}
94	
95	/** True when the document on disk is older than this build: the store must keep a pre-migration copy before writing. */
96	export function needsMigrationBackup(operationSchemaVersion: unknown): boolean {
97	  return operationSchemaVersion !== CURRENT_OPERATION_SCHEMA_VERSION;
98	}
99	
100	/** The effective concurrency for a state: an unset policy is the v1.0.0 behaviour, one unit at a time. */
101	export function effectiveConcurrency(state: Pick<DurableOperationState, "policy"> & Partial<Pick<DurableOperationState, "units">>): number {
102	  const requested = state.policy?.maxConcurrentUnits ?? 1;
103	  if (requested <= 1) return 1;
104	  return state.units && !parallelResourceBudgetProblem(state.policy, state.units) ? requested : 1;
105	}
106	
107	/** Explain why a parallel operation lacks enough explicit resource information for safe admission. */
108	export function parallelResourceBudgetProblem(
109	  policy: Partial<OperationPolicy> | undefined,
110	  units: ReadonlyArray<Pick<WorkUnit, "id" | "executionResources">>,
111	): string | undefined {
112	  if ((policy?.maxConcurrentUnits ?? 1) <= 1) return undefined;
113	  const budget = policy?.executionBudget;
114	  if (!budget) return "parallel execution requires policy.executionBudget with explicit cpuMilli and memoryBytes";
115	  for (const unit of units) {
116	    const request = unit.executionResources;
117	    if (!request) return `parallel execution requires work unit '${unit.id}'.executionResources with explicit cpuMilli and memoryBytes`;
118	    if (request.cpuMilli > budget.cpuMilli || request.memoryBytes > budget.memoryBytes) {
119	      return `work unit '${unit.id}' executionResources exceed policy.executionBudget`;
120	    }
121	  }
122	  return undefined;
123	}
