125	/**
126	 * Structural invariants that a scheduler or the store would otherwise trip over later, reported at load instead.
127	 * These are cheap checks, deliberately not a full schema: they catch the failures that would otherwise surface as a
128	 * confusing crash mid-run from a hand-edited or truncated file.
129	 */
130	export function validateOperationState(state: DurableOperationState): void {
131	  if (!OPERATION_STATUSES.has(state.status)) {
132	    throw new InvalidOperationStateError(`operation ${state.id}: invalid status (${String(state.status)})`);
133	  }
134	  if (!Array.isArray(state.units)) throw new InvalidOperationStateError("operation record has no units array");
135	  for (const field of ["resources", "conditions", "events"] as const) {
136	    if (!Array.isArray(state[field])) throw new InvalidOperationStateError(`operation ${state.id}: ${field} is not an array`);
137	  }
138	  if (!state.policy || typeof state.policy !== "object" || Array.isArray(state.policy)) {
