148	    }
149	  }
150	
151	  const ids = new Set<string>();
152	  for (const unit of state.units) {
153	    if (!unit || typeof unit !== "object") throw new InvalidOperationStateError(`operation ${state.id}: a work unit is not an object`);
154	    if (typeof unit.id !== "string" || !unit.id) throw new InvalidOperationStateError(`operation ${state.id}: a work unit has no id`);
155	    if (!WORK_UNIT_STATUSES.has(unit.status)) {
