170	    }
171	    validateAppliedDecisions(state.id, `unit '${unit.id}'`, unit.decisions);
172	    if (unit.blocked !== undefined) {
173	      const options = unit.blocked?.decision?.options;
174	      if (!Array.isArray(options)) {
