190	    }
191	  }
192	  for (const unit of state.units) {
193	    if (unit.executionResources !== undefined) validateExecutionResources(state.id, `work unit '${unit.id}'.executionResources`, unit.executionResources);
194	    for (const dependency of unit.dependsOn ?? []) {
