196	        throw new InvalidOperationStateError(`operation ${state.id}: unit '${unit.id}' depends on unknown unit '${dependency}'`);
197	      }
198	    }
199	  }
200	  validateConcurrency(state.id, "policy.maxConcurrentUnits", state.policy.maxConcurrentUnits);
201	  if (state.policy.executionBudget !== undefined) validateExecutionResources(state.id, "policy.executionBudget", state.policy.executionBudget);
202	  const hasResourceDeclarations = state.policy.executionBudget !== undefined || state.units.some((unit) => unit.executionResources !== undefined);
203	  if (hasResourceDeclarations) {
204	    const resourceProblem = parallelResourceBudgetProblem(state.policy, state.units);
