209	  }
210	  if (state.messages !== undefined) {
211	    if (!Array.isArray(state.messages)) throw new InvalidOperationStateError(`operation ${state.id}: messages is not an array`);
212	    for (const message of state.messages) {
213	      if (
214	        !message ||
215	        typeof message.id !== "string" ||
216	        typeof message.at !== "string" ||
217	        typeof message.kind !== "string" ||
218	        typeof message.body !== "string" ||
219	        typeof message.from !== "string" ||
