290	  }
291	  const keys = Object.keys(record);
292	  if (keys.length !== 2 || !keys.includes("cpuMilli") || !keys.includes("memoryBytes")) {
293	    throw new InvalidOperationStateError(`operation ${operationId}: ${field} must contain only cpuMilli and memoryBytes`);
294	  }
